export type HTTPMethod =  "GET" | "HEAD" | "PATCH" | "POST" | "PUT" | "DELETE" | "CONNECT" | "OPTIONS" | "TRACE" | "QUERY";

export interface H3Config {
  /**
   * When enabled, H3 displays debugging stack traces in HTTP responses (potentially dangerous for production!).
   */
  debug?: boolean;

  /**
   * When enabled, H3 console errors for unhandled exceptions will not be displayed.
   */
  silent?: boolean;

  /**
   * By default H3 rejects requests with a malformed percent-encoded URL path
   * (e.g. `/foo%`, `/%ZZ`) with a `400 Bad Request` before routing.
   *
   * When enabled, such requests are allowed through with the raw, undecoded
   * pathname instead. Your handlers are then responsible for handling it safely.
   */
  allowMalformedURL?: boolean;

  plugins?: H3Plugin[];

  onRequest?: (event: H3Event) => MaybePromise<void>;
  onResponse?: (response: Response, event: H3Event) => MaybePromise<void>;
  onError?: (error: HTTPError, event: H3Event) => MaybePromise<void | unknown>;
}

export type H3CoreConfig = Omit<H3Config, "plugins">;

export type PreparedResponse = ResponseInit & { body?: BodyInit | null };

export interface H3RouteMeta {
  readonly [key: string]: unknown;
  };
}

/**
 * Define a middleware that runs after Response is generated.
 *
 * You can return a new Response from the handler to replace the original response.
 */
export function onResponse(hook: (response: Response, event: H3Event) => unknown): Middleware {
  return async function _onResponseMiddleware(event, next) {
    const rawBody = await next();
    const response = await toResponse(rawBody, event);
    const hookResponse = await hook(response, event);
    return hookResponse || response;
  };
}

/**
 * Define a middleware that runs when an error occurs.
 *
 * You can return a new Response from the handler to gracefully handle the error.
## `H3` Options

You can pass global app configuration when initializing an app.

Supported options:

- `debug`: Displays debugging stack traces in HTTP responses (potentially dangerous for production!).
- `silent`: When enabled, console errors for unhandled exceptions will not be displayed.
- `allowMalformedURL`: When enabled, requests with a malformed percent-encoded URL path (e.g. `/foo%`, `/%ZZ`) are allowed through with the raw pathname instead of being rejected with a `400 Bad Request` (the default).
- `plugins`: (see [plugins](/guide/advanced/plugins) for more information)

> [!IMPORTANT]
> Enabling `debug` option, sends important stuff like stack traces in error responses. Only enable during development.

