import type { HTTPError } from "../../error.ts";

const reserved = new Set(["type", "title", "status", "detail", "instance"]);

/**
 * Build an RFC 9457 problem details object from an error.
 *
 * Standard members come first and cannot be overridden by `body` / `data` extensions.
 * `unhandled` errors only expose `title` and `status` (plus `stack` in debug mode).
 */
export function toProblemDetails(error: HTTPError, debug?: boolean): Record<string, unknown> {
  const { status, unhandled } = error;
  const title = error.statusText || STATUS_TEXT[status];
  const problem: Record<string, unknown> = unhandled
    ? { title, status }
    : {
        type: error.type,
        title,
        status,
        detail: error.message === title ? undefined : error.message,
        instance: error.instance,
      };

  if (!unhandled) {
    if (error.body) {
      assignExtensions(problem, error.body);
    }
    if (error.data !== undefined) {
      problem.data = error.data;
    }
  }

  if (debug && error.stack) {
    problem.stack = error.stack.split("\n").map((l) => l.trim());
  }

  return problem;
}

// --- internal ---

function assignExtensions(target: Record<string, unknown>, source: Record<string, unknown>) {
  for (const key of Object.keys(source)) {
    if (!reserved.has(key)) {
      target[key] = source[key];
    }
  }
}

